<?php if($items): ?><?= view('platform/order_pv',['items'=>$items]) ?><?php endif ?>
<section class="panel"><?php if(!$items): ?><div class="empty">ตะกร้ายังไม่มีสินค้า<br><a class="button" style="margin-top:20px" href="<?= site_url('shop') ?>">เลือกสินค้า</a></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>สินค้า</th><th>ราคา / ชิ้น</th><th>จำนวน</th><th>รวม</th></tr></thead><tbody><?php $total=0;foreach($items as $p):$total+=$p['price_satang']*$p['quantity']; ?><tr><td><a href="<?= site_url('shop/product/'.$p['id']) ?>"><?= esc($p['name']) ?></a><?php if(!$p['active']||$p['stock']<$p['quantity']): ?><p class="notice error">กรุณาลดจำนวนหรือลบสินค้านี้</p><?php endif ?></td><td><?php if(!empty($p['discount_satang'])): ?><del><?= p_money($p['original_price_satang']) ?></del><br><strong><?= p_money($p['price_satang']) ?></strong><small class="sn-cart-discount">ลด <?= esc(\App\Libraries\Platform\ProductPricing::discountLabel($p)) ?></small><?php else: ?><?= p_money($p['price_satang']) ?><?php endif ?></td><td><form class="inline-form" method="post"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><input aria-label="จำนวน <?= esc($p['name'],'attr') ?>" type="number" name="quantity" min="0" max="100" value="<?= $p['quantity'] ?>"><button class="small secondary">อัปเดต</button><span class="muted">ใส่ 0 เพื่อลบ</span></form></td><td><?= p_money($p['price_satang']*$p['quantity']) ?></td></tr><?php endforeach ?></tbody></table></div><div class="actions" style="justify-content:flex-end"><strong>รวม <?= p_money($total) ?></strong><a class="button" href="<?= site_url('checkout') ?>">ดำเนินการสั่งซื้อ →</a></div><?php endif ?></section>
